/bin/bash -c "python3 - <<'PY'
from itertools import combinations
from math import exp
obs=['H','V','R','Y']
true_edges={('U','H'),('U','V'),('H','R'),('C','R'),('C','Y'),('V','Y')}
alt_edges={('H','V'),('H','R'),('C','R'),('C','Y'),('V','Y')}
def dsep(edges,x,y,cond):
 nodes={n for e in edges for n in e}
 adj={n:set() for n in nodes}
 for a,b in edges: adj[a].add(b);adj[b].add(a)
 ancestors=set(cond)
 while True:
  new=ancestors|{a for a,b in edges if b in ancestors}
  if new==ancestors: break
  ancestors=new
 def paths(path):
  u=path[-1]
  if u==y:
   for a,b,c in zip(path,path[1:],path[2:]):
    collider=(a,b) in edges and (c,b) in edges
    if collider and b not in ancestors: return False
    if not collider and b in cond: return False
   return True
  return any(paths(path+[v]) for v in adj[u] if v not in path)
 return not paths([x])
def cis(edges):
 out=[]
 for a,b in combinations(obs,2):
  rem=set(obs)-{a,b}
  for k in range(len(rem)+1):
   for s in combinations(sorted(rem),k):
    if dsep(edges,a,b,set(s)):out.append((a,b,s))
 return out
print('True graph observed conditional independences:',cis(true_edges))
print('Alternative with H -> V -> Y:',cis(alt_edges))
p0=(1/(1+exp(.5))+1/(1+exp(-1.25)))/2
p1=(1/(1+exp(-2))+1/(1+exp(-3.75)))/2
print('P(Y=1 | H=0):',(p0+2*p1)/3)
print('P(Y=1 | H=1):',(2*p0+p1)/3)
PY"

